// ------------------------------------------------------------
// Node.js gateway middleware: DICOM‑Web → Proprietary legacy format
// GPU‑accelerated transcoding using gpu.js
// ------------------------------------------------------------

// ---------- Bibliotecas necessárias ----------
const express      = require('express');          // HTTP server & routing
const fetch        = require('node-fetch');       // HTTP client for DICOM‑Web
const dicomParser  = require('dicom-parser');    // DICOM parsing
const { GPU }      = require('gpu.js');           // GPU‑accelerated compute
const multer       = require('multer');           // multipart/form‑data handling
const path         = require('path');
const fs           = require('fs');
const os           = require('os');

// ---------- Configurações ----------
const PORT = process.env.PORT || 3000;
const DICOM_WEB_BASE = process.env.DICOM_WEB_BASE || 'http://dicomweb.example.com';
const LEGACY_OUTPUT_DIR = process.env.LEGACY_OUTPUT_DIR || path.join(os.tmpdir(), 'legacy');

// Cria diretório temporário se não existir
if (!fs.existsSync(LEGACY_OUTPUT_DIR)) fs.mkdirSync(LEGACY_OUTPUT_DIR, { recursive: true });

const app = express();
const upload = multer(); // para receber uploads multipart (se necessário)

// ---------- Instância GPU ----------
const gpu = new GPU({
  mode: 'gpu',               // força uso da GPU quando disponível
  canvas: undefined,        // headless (node) usa node‑canvas internally
  webGL: undefined
});

// ---------- Função de transcoding (exemplo) ----------
/**
 * Converte um buffer de pixel (Uint8Array) de um plano DICOM para
 * o formato proprietário (ex.: 16‑bit signed little‑endian).
 * Esta implementação usa gpu.js para acelerar a operação de escala.
 *
 * @param {Uint8Array} srcBuffer   Buffer de pixel original (8‑bit)
 * @param {number}    width        Largura da imagem
 * @param {number}    height       Altura da imagem
 * @returns {Uint16Array}          Buffer convertido
 */
function gpuTranscode8to16(srcBuffer, width, height) {
  // Cria kernel que converte cada pixel de 8‑bit para 16‑bit (ex.: escala 0‑255 → 0‑65535)
  const kernel = gpu.createKernel(function (src) {
    const idx = this.thread.y * this.constants.width + this.thread.x;
    const val8 = src[idx];
    // Exemplo de operação intensiva: elevação ao quadrado + normalização
    const val16 = Math.pow(val8 / 255.0, 2.0) * 65535.0;
    return Math.round(val16);
  })
    .setOutput([width, height])
    .setConstants({ width })
    .setPipeline(true); // devolve textura GPU, converte depois

