 *  - JSON → PDF: usa `pdfmake` para gerar documentos com tabelas e estilos configuráveis.
 *
 * O script detecta o tipo de entrada pelo sufixo do arquivo (.html/.htm ou .json)
 * e escolhe a estratégia apropriada.
 */

import { readFile, writeFile } from 'node:fs/promises';
import { resolve, extname } from 'node:path';
import puppeteer from 'puppeteer';
import PdfPrinter from 'pdfmake';

// -----------------------------------------------------------------------------
// Configurações padrão do pdfmake (fontes)
// -----------------------------------------------------------------------------
const fonts = {
  Roboto: {
    normal:   resolve('node_modules/pdfmake/build/vfs_fonts.js'), // fallback para fontes internas
    bold:     resolve('node_modules/pdfmake/build/vfs_fonts.js'),
    italics:  resolve('node_modules/pdfmake/build/vfs_fonts.js'),
    bolditalics: resolve('node_modules/pdfmake/build/vfs_fonts.js')
  }
};
const printer = new PdfPrinter(fonts);

// -----------------------------------------------------------------------------
// Função: converte HTML → PDF usando puppeteer
// -----------------------------------------------------------------------------
async function htmlToPdf(htmlPath, pdfPath) {
  const browser = await puppeteer.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });

  try {
    const page = await browser.newPage();

    // Carrega o HTML local (mantém caminho relativo para recursos)
    const absoluteHtml = resolve(htmlPath);
    await page.goto(`file://${absoluteHtml}`, { waitUntil: 'networkidle0' });

    // Configurações de impressão (margens, formato, etc.)
    const pdfOptions = {
      path: pdfPath,
      format: 'A4',
      printBackground: true,
      margin: { top: 20, right: 20, bottom: 20, left: 20 }
    };

    await page.pdf(pdfOptions);
    console.log(`✅ PDF gerado a partir de HTML → ${pdfPath}`);
  } finally {
    await browser.close();
  }
}

